from typing import List
from collections import deque, defaultdict

def numBusesToDestination(routes: List[List[int]], S: int, T: int) -> int:
    if S == T:
        return 0

    # Create a graph where each node is a bus stop and edges represent direct connections between stops
    stop_to_routes = defaultdict(set)
    for route_index, route in enumerate(routes):
        for stop in route:
            stop_to_routes[stop].add(route_index)

    # If either S or T is not in any route, return -1
    if S not in stop_to_routes or T not in stop_to_routes:
        return -1

    # BFS initialization
    queue = deque([(S, 0)])  # (current_stop, current_bus_count)
    visited_stops = set([S])
    visited_routes = set()

    while queue:
        current_stop, bus_count = queue.popleft()

        # Check all routes passing through the current stop
        for route_index in stop_to_routes[current_stop]:
            if route_index in visited_routes:
                continue
            visited_routes.add(route_index)

            # Check all stops in the current route
            for next_stop in routes[route_index]:
                if next_stop == T:
                    return bus_count + 1
                if next_stop not in visited_stops:
                    visited_stops.add(next_stop)
                    queue.append((next_stop, bus_count + 1))

    return -1
